package cn.kecheng.assistant;
import android.animation.*;
import android.app.*;
import android.graphics.*;
import android.media.*;
import android.os.*;
import android.view.*;
import android.view.animation.DecelerateInterpolator;
import android.widget.*;
import org.json.*;
import java.security.SecureRandom;
import java.util.*;

public final class FunTools {
 final Activity activity;final Store store;final SecureRandom random=new SecureRandom();final Handler handler=new Handler(Looper.getMainLooper());
 FunTools(Activity a,Store s){activity=a;store=s;}
 int dp(float v){return Ui.dp(activity,v);}TextView text(String s,float size){return Ui.text(activity,s,size,Ui.INK);}LinearLayout form(){LinearLayout p=Ui.column(activity);Ui.pad(p,20,20,20,20);return p;}
 void feedback(boolean wood){if(store.vibration){Vibrator v=(Vibrator)activity.getSystemService(Activity.VIBRATOR_SERVICE);if(v!=null&&v.hasVibrator())v.vibrate(VibrationEffect.createOneShot(wood?18:30,VibrationEffect.DEFAULT_AMPLITUDE));}if(store.sound)new Thread(()->{AudioTrack track=null;try{int rate=22050,count=rate/5;short[] pcm=new short[count];double freq=wood?720:1050;for(int n=0;n<count;n++){double t=n/(double)rate;pcm[n]=(short)(Math.exp(-t*(wood?28:18))*Math.sin(2*Math.PI*freq*t)*10000+(wood?Math.sin(2*Math.PI*freq*1.63*t)*Math.exp(-t*40)*2800:0));}track=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(rate).setEncoding(AudioFormat.ENCODING_PCM_16BIT).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).build()).setBufferSizeInBytes(count*2).setTransferMode(AudioTrack.MODE_STATIC).build();track.write(pcm,0,count);track.play();Thread.sleep(230);}catch(Exception ignored){}finally{if(track!=null)track.release();}},"tool-audio").start();}
 public void dice(){LinearLayout p=form();TextView result=text("⚄",60);result.setGravity(17);Ui.pad(result,0,16,0,16);p.addView(result);TextView total=text("点击投掷",15);total.setGravity(17);p.addView(total);Ui.gap(p,16);Spinner count=new Spinner(activity);count.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,new String[]{"1 个骰子","2 个骰子","3 个骰子","4 个骰子","5 个骰子","6 个骰子"}));p.addView(count);Button roll=Ui.button(activity,"投掷",()->{});p.addView(roll);ValueAnimator[] animation=new ValueAnimator[1];roll.setOnClickListener(v->{roll.setEnabled(false);ValueAnimator a=ValueAnimator.ofFloat(0,1);animation[0]=a;a.setDuration(550);a.addUpdateListener(x->{result.setText("⚀ ⚂ ⚄");result.setRotation((float)x.getAnimatedValue()*8-4);});a.addListener(new AnimatorListenerAdapter(){public void onAnimationEnd(Animator x){if(!roll.isAttachedToWindow())return;StringBuilder glyphs=new StringBuilder(),numbers=new StringBuilder();int sum=0;for(int n=0;n<=count.getSelectedItemPosition();n++){int value=1+random.nextInt(6);sum+=value;if(n>0){glyphs.append(' ');numbers.append(" + ");}glyphs.append((char)(0x267f+value));numbers.append(value);}result.setRotation(0);result.setText(glyphs);result.setTextSize(count.getSelectedItemPosition()>2?38:60);total.setText(numbers+" = "+sum);roll.setEnabled(true);feedback(false);}});a.start();});AlertDialog d=new AlertDialog.Builder(activity).setTitle("骰子").setView(p).setNegativeButton("返回",null).create();d.setOnDismissListener(x->{if(animation[0]!=null)animation[0].cancel();});d.show();}
 public void wood(){LinearLayout p=form();TextView count=text("已敲 "+store.wood+" 次",18);count.setGravity(17);p.addView(count);Ui.gap(p,20);WoodView wood=new WoodView(activity);p.addView(wood,new LinearLayout.LayoutParams(-1,dp(190)));wood.setContentDescription("点击敲木鱼");wood.setOnClickListener(v->{if(store.wood<Integer.MAX_VALUE)store.wood++;if(!store.save())return;count.setText("已敲 "+store.wood+" 次");wood.animate().cancel();wood.setScaleX(.93f);wood.setScaleY(.93f);wood.animate().scaleX(1).scaleY(1).setDuration(180).start();feedback(true);});Ui.gap(p,12);TextView hint=text("轻轻敲一下，放松一下",13);hint.setGravity(17);p.addView(hint);new AlertDialog.Builder(activity).setTitle("木鱼").setView(p).setNegativeButton("返回",null).setNeutralButton("重置次数",(d,w)->new AlertDialog.Builder(activity).setTitle("清空累计次数？").setPositiveButton("重置",(a,b)->{store.wood=0;store.save();wood();}).setNegativeButton("取消",null).show()).show();}
 static class WoodView extends View {Paint p=new Paint(3);WoodView(Activity c){super(c);}protected void onDraw(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(getWidth(),getHeight())*.32f;p.setShader(new RadialGradient(cx-r*.3f,cy-r*.4f,r*1.8f,new int[]{0xffdab785,0xff9c6741},null,Shader.TileMode.CLAMP));c.drawOval(cx-r,cy-r*.7f,cx+r,cy+r*.7f,p);p.setShader(null);p.setColor(0xff67422d);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(r*.08f);c.drawArc(cx-r*.6f,cy-r*.3f,cx+r*.6f,cy+r*.3f,10,160,false,p);c.drawLine(cx-r*.1f,cy+r*.05f,cx+r*.55f,cy+r*.1f,p);p.setStyle(Paint.Style.FILL);}}
 public void wheel(){LinearLayout p=form();if(store.wheels.length()==0){p.addView(text("创建一个转盘，例如“今天吃什么”。",15));}else for(int n=0;n<store.wheels.length();n++){JSONObject wheel=store.wheels.optJSONObject(n);int index=n;Button open=Ui.button(activity,wheel.optString("name"),()->spin(index));p.addView(open);}
  p.addView(Ui.button(activity,"＋ 新建转盘",()->wheelEditor(-1)));new AlertDialog.Builder(activity).setTitle("我的转盘").setView(p).setNegativeButton("返回",null).show();}
 void wheelEditor(int index){LinearLayout p=form();EditText name=new EditText(activity);name.setHint("转盘名称");p.addView(name);EditText options=new EditText(activity);options.setHint("每行一个选项，至少2项、最多20项");options.setMinLines(4);options.setGravity(48);p.addView(options);if(index>=0){JSONObject j=store.wheels.optJSONObject(index);name.setText(j.optString("name"));JSONArray a=j.optJSONArray("options");StringBuilder s=new StringBuilder();for(int n=0;n<a.length();n++)s.append(a.optString(n)).append('\n');options.setText(s);}
  AlertDialog d=new AlertDialog.Builder(activity).setTitle(index<0?"新建转盘":"编辑转盘").setView(p).setPositiveButton("保存",null).setNegativeButton("取消",null).setNeutralButton("删除",null).create();d.setOnShowListener(x->{if(index<0)d.getButton(-3).setVisibility(8);d.getButton(-1).setOnClickListener(v->{try{String title=name.getText().toString().trim();if(title.isEmpty())throw new Exception("请填写名称");JSONArray a=new JSONArray();Set<String> seen=new HashSet<>();for(String line:options.getText().toString().split("\\n")){String s=line.trim();if(!s.isEmpty()){if(s.length()>30)throw new Exception("选项最多30个字符");if(!seen.add(s))throw new Exception("选项不能重复");a.put(s);}}if(a.length()<2||a.length()>20)throw new Exception("需要2至20个不同选项");JSONObject j=new JSONObject().put("name",title).put("options",a);if(index<0)store.wheels.put(j);else store.wheels.put(index,j);if(!store.save())return;d.dismiss();wheel();}catch(Exception e){Toast.makeText(activity,e.getMessage(),1).show();}});d.getButton(-3).setOnClickListener(v->new AlertDialog.Builder(activity).setTitle("删除这个转盘？").setPositiveButton("删除",(a,b)->{store.wheels.remove(index);if(!store.save())return;d.dismiss();wheel();}).setNegativeButton("取消",null).show());});d.show();}
 void spin(int index){JSONObject j=store.wheels.optJSONObject(index);JSONArray arr=j.optJSONArray("options");List<String> items=new ArrayList<>();for(int i=0;i<arr.length();i++)items.add(arr.optString(i));LinearLayout p=form();WheelView view=new WheelView(activity,items);p.addView(view,new LinearLayout.LayoutParams(-1,dp(250)));TextView result=text("每个选项概率相同",17);result.setGravity(17);p.addView(result);Ui.gap(p,10);Button spin=Ui.button(activity,"转一下",()->{});p.addView(spin);ValueAnimator[] animator=new ValueAnimator[1];spin.setOnClickListener(v->{int selected=random.nextInt(items.size());float step=360f/items.size();float target=360*5-(selected+.5f)*step;float start=view.angle%360;if(start<0)start+=360;ValueAnimator a=ValueAnimator.ofFloat(start,target);animator[0]=a;a.setDuration(2400);a.setInterpolator(new DecelerateInterpolator(2));spin.setEnabled(false);result.setText("转动中…");a.addUpdateListener(x->{view.angle=(float)x.getAnimatedValue();view.invalidate();});a.addListener(new AnimatorListenerAdapter(){public void onAnimationEnd(Animator x){if(!spin.isAttachedToWindow())return;result.setText(items.get(selected));spin.setEnabled(true);feedback(false);}});a.start();});AlertDialog d=new AlertDialog.Builder(activity).setTitle(j.optString("name")).setView(p).setNegativeButton("返回",null).setNeutralButton("编辑",(a,b)->wheelEditor(index)).create();d.setOnDismissListener(x->{if(animator[0]!=null)animator[0].cancel();});d.show();}
 static class WheelView extends View {final List<String> items;float angle;Paint p=new Paint(3);final int[] colors={0xffc1dfdc,0xffe5edda,0xfff3dfc8,0xffcedded,0xffe8d7e5};WheelView(Activity a,List<String> l){super(a);items=l;}protected void onDraw(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(getWidth(),getHeight())*.4f,step=360f/items.size();c.save();c.rotate(angle,cx,cy);for(int n=0;n<items.size();n++){p.setColor(colors[n%colors.length]);p.setStyle(Paint.Style.FILL);c.drawArc(cx-r,cy-r,cx+r,cy+r,-90+n*step,step,true,p);c.save();c.rotate(n*step+step/2,cx,cy);p.setColor(Ui.INK);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(Ui.dp(getContext(),items.size()>8?10:12));String s=items.get(n);if(s.length()>7)s=s.substring(0,6)+"…";c.drawText(s,cx,cy-r*.6f,p);c.restore();}c.restore();p.setColor(Ui.TEAL);Path triangle=new Path();triangle.moveTo(cx-9,cy-r-10);triangle.lineTo(cx+9,cy-r-10);triangle.lineTo(cx,cy-r+12);triangle.close();c.drawPath(triangle,p);}}
}
